 pub fn paint_round(&mut self,r:Rect,radius:u32,fill:u32,edge:u32,edge_points:u32){if !self.valid(){return}let Some(p)=self.pixel_rect(r)else{return};let right=p.x.saturating_add(p.width).min(self.width);let bottom=p.y.saturating_add(p.height).min(self.height);let s=self.scale();let rad=(radius as f64*s).min(p.width as f64/2.0).min(p.height as f64/2.0);let inset=edge_points as f64*s;for y in p.y..bottom{for x in p.x..right{let(mut fc,mut ec)=(0u32,0u32);for sy in 0..4{for sx in 0..4{let xx=x as f64+(sx as f64+0.5)/4.0;let yy=y as f64+(sy as f64+0.5)/4.0;if rounded(xx,yy,p.x as f64,p.y as f64,(p.x+p.width)as f64,(p.y+p.height)as f64,rad){if edge_points>0&&inside_inner(xx,yy,p,inset,(rad-inset).max(0.0)){if fill!=0{fc+=1}}else if edge_points>0{ec+=1}else if fill!=0{fc+=1}}}}if fc>0{self.pixel(x,y,fill,((fc*255+8)/16)as u8)}if ec>0&&edge!=0{self.pixel(x,y,edge,((ec*255+8)/16)as u8)}}}}
