/// Paint one widget. All borrowed text and the target buffer remain caller-owned.
pub fn widget_paint(c:&mut WidgetCanvas<'_>,spec:&WidgetDrawSpec<'_>)->bool{if !c.valid()||spec.kind==WidgetKind::Auto||spec.kind==WidgetKind::Count||spec.bounds.width==0||spec.bounds.height==0||spec.bounds.width>MAX_CANVAS_AXIS||spec.bounds.height>MAX_CANVAS_AXIS||spec.bounds.x.checked_add(spec.bounds.width).and_then(|v|v.checked_add(128)).is_none()||spec.bounds.y.checked_add(spec.bounds.height).and_then(|v|v.checked_add(128)).is_none()||spec.segment_count>8||spec.segment_labels.len()>8||[spec.label,spec.value,spec.secondary,spec.unit].iter().flatten().any(|v|v.len()>MAX_TEXT_BYTES)||spec.segment_labels.iter().any(|v|v.len()>MAX_TEXT_BYTES)||spec.unit.is_some_and(|v|v.len()>8){return false}let mut adjusted=*spec;if adjusted.kind==WidgetKind::Toast&&adjusted.bounds.width>360{adjusted.bounds.width=360}let s=&adjusted;let fg=c.state_fg(s.state);let label=text(s.label);let result=match s.kind{
 WidgetKind::Label=>c.text(label,s.bounds,if s.text_color==0{fg}else{s.text_color},s.font_family,s.font_weight,if s.font_size_pt==0{13}else{s.font_size_pt as u32}),
