 WidgetKind::Auto|WidgetKind::Count=>false};if result&&(s.focus_visible||s.state==ControlState::Focus){let mut r=s.bounds;if s.kind==WidgetKind::Dropdown&&s.expanded{r.height=30}let l=r.x.saturating_sub(3);let t=r.y.saturating_sub(3);let right=r.x.saturating_add(r.width).saturating_add(3);let bottom=r.y.saturating_add(r.height).saturating_add(3);c.paint_round(Rect{x:l,y:t,width:right-l,height:bottom-t},9,0,c.tokens.focus_ring,2)}result}
pub const fn widget_paint_scratch_limit()->usize{0}

fn draw_button(c:&mut WidgetCanvas<'_>,s:&WidgetDrawSpec<'_>,mut fg:u32)->bool{let icon_only=s.kind==WidgetKind::IconButton;let primary=s.kind==WidgetKind::ButtonPrimary;let mut surface=c.state_surface(s.state,if primary{c.tokens.accent}else if s.kind==WidgetKind::ButtonSecondary{c.tokens.panel_raised}else{0});if s.has_transition&&(icon_only||s.kind==WidgetKind::ButtonGhost){surface=blend_color(s.transition_from_color,s.transition_to_color,s.transition_progress_permille)}if primary&&s.state==ControlState::Pressed{surface=if c.theme==Theme::Light{0x124b97ff}else{c.tokens.selection_fill}}if primary&&s.state!=ControlState::Disabled{fg=if c.theme==Theme::Light{0xffffffff}else if s.state==ControlState::Pressed{c.tokens.text_primary}else{c.tokens.window}}if surface!=0{c.paint_round(s.bounds,6,surface,0,0)}if icon_only{let size=(if s.icon==IconKind::CLOSE{14}else{22}).min(s.bounds.width).min(s.bounds.height);return c.icon(s.icon,Rect{x:s.bounds.x+(s.bounds.width-size)/2,y:s.bounds.y+(s.bounds.height-size)/2,width:size,height:size},s.state,if s.icon==IconKind::CLOSE&&s.state==ControlState::Rest{Some(c.tokens.text_secondary)}else{None})}if s.icon!=IconKind::None&&!c.icon(s.icon,Rect{x:s.bounds.x+8,y:s.bounds.y+s.bounds.height.saturating_sub(16)/2,width:16,height:16},s.state,None){return false}c.text(text(s.label),inset(s.bounds,if s.icon==IconKind::None{8}else{28},0,8,0),fg,FontFamily::System,FontWeight::Regular,FONT_PT)}
