fn middle_ellipsis(s:&str,max:usize)->String{let count=s.chars().count();if count<=max&&s.len()<64{return s.to_owned()}if max==0{return String::new()}let mut left=max/2;let mut right=max-left-1;let mut a:usize=s.char_indices().nth(left).map_or(s.len(),|(i,_)|i);let mut start=s.char_indices().nth(count.saturating_sub(right)).map_or(s.len(),|(i,_)|i);let mut bytes=s.len()-start;while a+3>=64&&left>0{left-=1;a=s.char_indices().nth(left).map_or(s.len(),|(i,_)|i)}while a+3+bytes>=64&&right>0{right-=1;start=s.char_indices().nth(count.saturating_sub(right)).map_or(s.len(),|(i,_)|i);bytes=s.len()-start}format!("{}…{}",&s[..a],&s[start..])}
